#include "batched_slot_plan.hpp"
#include <cstdio>
int main(){using namespace tao::data;std::vector<std::vector<Token>>docs;for(int n:{3,9,4,7,5}){std::vector<Token>d;d.push_back({BOS,false});for(int i=1;i<n-1;++i)d.push_back({65+i,bool(i%2)});d.push_back({TURN_END,true});docs.push_back(d);}PilotCursor a(docs,4,false),b(docs,4,false);size_t total=0;for(int round=0;round<5;++round){auto plan=take_batch(a,3);for(size_t k=0;k<4;++k){Work w;bool valid=b.take(k,3,w);for(size_t t=0;t<plan.timesteps;++t){auto&p=plan.items[t*4+k];bool active=valid&&t<w.end-w.begin;if(p.active!=active)return 1;if(active){size_t i=w.begin+t;if(p.input!=b.docs[w.doc][i-1].id||p.target!=b.docs[w.doc][i].id||p.loss!=bool(b.docs[w.doc][i].loss)||p.reset!=(t==0&&w.reset))return 2;}else if(p.loss||p.reset)return 3;}}if(a.next!=b.next)return 4;for(size_t k=0;k<4;++k)if(a.slots[k].doc!=b.slots[k].doc||a.slots[k].target!=b.slots[k].target)return 5;total+=plan.positions;}printf("PASS lockstep plan retains serial cursor ordering positions=%zu padding/reset/loss checked\n",total);return 0;}
